  w=getattr(getattr(models,enum),member);modelid='torchvision.models.'+enum+'.'+member;filename=w.url.split('/')[-1];source_file=__import__(getattr(models,builder).__module__,fromlist=['_']).__file__;local_source=OUT/'sources'/Path(source_file).name;shutil.copyfile(source_file,local_source)
  row={'task':'image','model_id':modelid,'revision':'torchvision0.29.0:'+filename,'weight_url':w.url,'filename':filename,'expected_sha256_prefix':filename.split('-')[-1].split('.')[0],'published_quality_metric':'ImageNet-1K top1 accuracy %','published_quality':w.meta['_metrics']['ImageNet-1K']['acc@1'],'published_baseline_ResNet50_v2_quality':models.ResNet50_Weights.IMAGENET1K_V2.meta['_metrics']['ImageNet-1K']['acc@1'],'published_quality_comparable_to_frozen_Imagenette':False,'parameter_count_metadata':w.meta['num_params'],'size_memory_latency_are_not_estimated_measurements':True,'semantics_status':'TASK_SEMANTICS_COMPATIBLE','local_inference_path':'torchvision native FP32 strict load_state_dict + official weight transform + closed-set10 logits','preprocessing':str(w.transforms()),'builder':builder,'weight_enum':enum,'weight_member':member,'published_source':'https://github.com/pytorch/vision/blob/main/torchvision/models/'+Path(source_file).name,'local_implementation':ref(local_source),'frozen_shortlisted':selected,'RTX4090_feasibility':'Native FP32 batch1 expected within24GiB; actual host49140MiB; only local measurement establishes residency'}
