 for r in discovery['records']:
  repo=r['model_id'];api=read(OUT/'sources'/(repo.replace('/','--')+'.api.json'));is_paddle=repo.startswith('PaddlePaddle/');weights=['inference.pdiparams'] if is_paddle else ['model.safetensors'] if any(x['rfilename']=='model.safetensors' for x in api['siblings']) else ['pytorch_model.bin'];row={'task':'ocr','model_id':repo,'revision':r['revision'],'weight_files':weights,'observable_weight_bytes':sum(x['size'] for x in api['siblings'] if x['rfilename'] in weights),'published_quality_metric':published[repo][0],'published_quality':published[repo][1],'published_quality_comparable_to_frozen_IIIT5K200':False,'quality_evidence_status':'UNKNOWN_COMPARATIVE; scores/datasets differ from local baseline, no claimed local quality improvement','semantics_status':'TASK_SEMANTICS_COMPATIBLE','input':'existing IIIT5K word crop; recognition only; no detection or orientation pipeline','local_inference_path':'PaddleOCR TextRecognition native paddle_static FP32 batch1' if is_paddle else 'TrOCRProcessor + VisionEncoderDecoderModel FP32 native generation defaults','published_source':'https://huggingface.co/'+repo,'secondary_source':'https://github.com/PaddlePaddle/PaddleOCR/blob/main/docs/version3.x/module_usage/text_recognition.en.md' if is_paddle else 'https://github.com/microsoft/unilm/blob/master/trocr/README.md','frozen_shortlisted':repo in selected,'no_required_finetuning':True,'preprocessing':'same BGR file decode then checkpoint-native recognition frontend' if is_paddle else 'same existing crop decoded RGB; exact checkpoint-native TrOCRProcessor; same lowercase a-z/0-9 scorer; no crop/detection/rectification added','RTX4090_feasibility':'FP32 single recognizer expected within24GiB; real memory measured separately'}
  ocruniverse.append(row)
  if repo in selected:
   cfg=read(OUT/'sources'/(repo.replace('/','--')+'__generation_config.json')) if not is_paddle else None
   ocr.append({**row,'backend':'paddle' if is_paddle else 'trocr','directory':str(MODELS/repo.replace('/','--')),'native_generation_config':cfg,'generation_policy':'exact archived checkpoint generation_config defaults; do_sample=False; no extra beam/length tuning' if not is_paddle else 'native pretrained decoder, batch1, no language-model or lexicon postprocessing'})
 ocr.sort(key=lambda r:selected.index(r['model_id']));csvsave('ocr_candidate_universe.csv',ocruniverse)
 policy={'criteria':['published quality improvement over comparable baseline evidence preferred, never cross-dataset score substitution','architecture/model-scale diversity','reproducible native local deployment','deterministic full model ID'], 'Image_rationale':'All3 shortlisted official ImageNet1K checkpoints improve published ResNet50-v2 ImageNet1K quality; choose one per CNN/ViT/Swin family. No architecture can exceed frozen measured Imagenette baseline accuracy1.0. ConvNeXt-large chosen over base by same published ImageNet metric.', 'OCR_rationale':'No public score establishes superiority on frozen200 crops. Choose mature high-capacity multilingual document/server recognizers at distinct scales and a large Transformer directly pretrained for scene-word recognition. PP-OCRv6 has no public large tier above medium. Full-image pipeline and detection-only models are not candidates; TrOCR is compatible with actual supplied crops. All6 real candidates retained in universe.', 'deployment_or_V3_outcomes_used':False}
 for task,entries in [('image',images),('ocr',ocr)]:save(task+'_measurement_shortlist.json',{'at_utc':now(),'frozen':True,'before_any_new_GPU_measurement':True,'selection_policy':policy,'entries':entries})
 definitions=read(ROOT/'results/candidate_pool_v2/task_definitions.json');pool=[json.loads(x) for x in (ROOT/'benchmark/task_pools/mixed_formal_1200_6task.jsonl').read_text().splitlines()];datasets={};inputfiles={}
 for task in ['image','ocr','asr','lid','text']:
  d=definitions[task];quality=Path(d['evaluation_manifest']);rows=[json.loads(x) for x in quality.read_text().splitlines()];assert len(rows)==200;lat=[r for r in pool if r['task_type']==task][:30];assert len(lat)==30
  p=OUT/('latency_samples_'+task+'.jsonl');p.write_text(''.join(json.dumps(r)+'\n' for r in lat));datasets[task]={'definition':d['definition'],'dataset':d['dataset'],'split':d['split'],'quality_manifest':ref(quality),'quality_n':200,'quality_ids_in_order':[r['id'] for r in rows],'metric':d['metric'],'preprocessing':d['preprocessing'],'latency_sample_file':ref(p),'latency_ids_in_order':[r['pool_id'] for r in lat]}
  if task!='text':
   for row in rows+[r['sample'] for r in lat]:
    p=Path(row['input']);inputfiles[str(p)]=ref(p)
 save('dataset_input_hashes.json',{'files':list(inputfiles.values())})
 existing=list(csv.DictReader((OUT/'existing_heavy_candidate_audit.csv').open()));eligible={task:[r['model_id'] for r in existing if r['task']==task and r['HQ_HEAVY_ELIGIBLE']=='True'] for task in ['asr','lid','text']}
 # Existing published checkpoints with real frozen task-path measurements are
 # eligible for reuse. Regimes are independently described, never overwritten.
 assert all(eligible.values())
 save('gap_filling_freeze.json',{'at_utc':now(),'frozen':True,'rounds_allowed':1,'rounds_used':0,'eligible_existing_paths':eligible,'scope':'Complete13B operating-point table including its real legacy alternatives; canonical denominator references fixed','user_preference_question':'No answer at freeze; use stated default allowing reuse of real existing checkpoint. Two regimes remain independent, baseline intact.','missing_tasks':[],'entries':[],'no_iterative_search_or_deployment_conditioning':True})
 csvsave('gap_filling_candidates.csv',[],['task','model_id','revision','status','reason'])
 save('measurement_protocol_freeze.json',{'at_utc':now(),'frozen':True,'before_any_Module14_GPU_measurement':True,'entries':images+ocr,'datasets':datasets,'quality_phase':'Complete all6 frozen quality evaluations before standalone performance; performance retained for every path, including quality failures and ceiling-limited Image','latency_repetitions':3,'requests_per_repetition':30,'warmup_per_fresh_process':1,'latency_estimator':'sample-count weighted arithmetic mean all3x30 worker service times','timer':'unchanged READY/RESULT/BYE worker_protocol handler timer; include file decode, full checkpoint-native preprocessing, H2D, inference/generation, synchronization, decode/scoring; no synthetic forward benchmark','measurement_order':'Quality: three Image then three OCR frozen list order. Latency: repetitions1,2,3; in each Image baseline control first then three candidates; OCR baseline control first then three candidates','idle_memory':'after one same frozen first-sample warmup, observe process NVML idle5seconds at100ms; arithmetic mean samples, then mean independent3runs','peak_memory':'NVML10ms sampled full quality and latency inference peaks; report separately from frozen-safe definition','safe_memory':'original factor * measured mean post-warmup idle process MiB; same unchanged baseline factor','dtype':'float32 all native models; no autocast, quantization, compile, CPU/offload, inference-time augmentation or ensemble','threads':{'OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1','OPENBLAS_NUM_THREADS':'1'},'worker_architecture':'one native model process, one outstanding request; no other GPU compute process allowed','preprocessing_policy':'Original frozen task definitions permit pretrained checkpoint-native input transforms. Image always original RGB file + native official weight transform + fixed10-logit gather. OCR always original supplied crop; native BGR for Paddle / RGB TrOCR; native recognizer preprocessing + same lowercase alphanumeric exact match. No detection or crop-generation stage.', 'baseline_anchors':ref(OUT/'baseline_references.json'),'selection_rule':{'eligibility':'exact Qutility_new>Qutility_old AND s0_new>s0_old AND safeM_new>safeM_old. Equality fails. No Pareto-dominated exclusion. Missing measurements never eligible.','order':['higher full-precision quality utility (-WER for ASR)','lower s0 among exact quality ties','lower safe memory','lexicographic model_id@revision'],'include_existing_legacy_alternatives':True,'Generalist_or_deployment_outcomes_used':False},'HQ_SLO_CONSTRUCTION_RULE_BEFORE_OUTCOMES':'After all frozen candidates finish, for eligible selected task use arithmetic midpoint(old baseline Q,selected HQ Q), >= for accuracy/exact_match, <= for ASR WER, retain semantic admission. Must strictly strengthen old numeric SLO where present, reject baseline, admit selected model. Missing task gets null SLO with explicit NO_ELIGIBLE_HEAVY_SPECIALIST; do not set accuracy>1. No full five-task HQ SLO/regime claimed unless all5 tasks eligible. Numeric values frozen once after measurement; no deployment reference.','prohibitions':['No deployment/structural replay','No lowQPS/multi-hotspot','No g(x>1)/replica frontier','No task/dataset/oldSLO/oldregime mutation','No artificial slowdown or memory scaling','No second-round gap filling']})
 refs=[ref(OUT/n) for n in ['baseline_references.json','existing_heavy_candidate_audit.csv','image_candidate_universe.csv','ocr_candidate_universe.csv','image_measurement_shortlist.json','ocr_measurement_shortlist.json','measurement_protocol_freeze.json','gap_filling_freeze.json','dataset_input_hashes.json']]+[ref(OUT/('latency_samples_'+t+'.jsonl')) for t in datasets]
 save('discovery_freeze_manifest.json',{'at_utc':now(),'files':refs,'before_any_new_GPU_measurement':True})
